import random

def list_of_hexa_colors(count, seed=None):
    if seed is not None:
        random.seed(seed)
    hex_chars = '0123456789abcdef'
    colors = []
    for _ in range(count):
        color = '#' + ''.join(random.choice(hex_chars) for _ in range(6))
        colors.append(color)
    return colors
